export function normalizeSkill(input                             )                 {
  const raw = input              
  const when = String(raw.when_to_use ?? raw.when ?? '').replace(/\s+/gu, ' ').trim()
  const steps = (raw.steps ?? raw.how ?? []).map((step) => String(step).replace(/\s+/gu, ' ').trim()).filter(Boolean)
  const verify = (raw.verify ?? raw.verification ?? []).map((line) => String(line).replace(/\s+/gu, ' ').trim()).filter(Boolean)
  const scope = String(raw.scope ?? '').toLowerCase()
  const scene = String((raw       ).scene ?? '').trim().toLowerCase()
  const aliases = (Array.isArray(raw.aliases) ? raw.aliases : [])
    .map((alias) => String(alias).replace(/\s+/gu, ' ').trim())
    .filter(Boolean)
    .slice(0, 3)
  /**
   * GLOBAL KNOWLEDGE BASE — carried through the normaliser for the same reason `dependencies`
   * had to be: `normalizeSkill` rebuilds the record from a whitelist, so a field it does not name
   * is silently dropped. A skill written with tags and read back without them looks local, and the
   * whole point of the field is that it is not.
   */
  const tags = asVocab((raw       ).tags)
  const applicableNodeTypes = asVocab((raw       ).applicableNodeTypes ?? (raw       ).applicable_node_types)
  // v0.6: accept legacy numbers (a bare seq is resolved against the write's
  // session id) and composite refs (already carry their own session id).
  const evidence                = []
  for (const item of Array.isArray(raw.evidence) ? raw.evidence : []) {
    if (item !== null && typeof item === 'object' && typeof (item               ).seq !== 'undefined') {
      const seq = Number((item               ).seq)
      const sourceSessionId = String((item               ).sourceSessionId ?? '')
      if (Number.isFinite(seq) && !evidence.some((ref) => ref.seq === seq && ref.sourceSessionId === sourceSessionId)) {
        evidence.push({ sourceSessionId, seq })
      }
      continue
    }
    const seq = Number(item)
    if (Number.isFinite(seq)) evidence.push({ sourceSessionId: '', seq })
  }
  return {
    name: String(raw.name ?? '').toLowerCase(),
    title: String(raw.title ?? raw.name ?? ''),
    description: String(raw.description ?? when).replace(/\s+/gu, ' ').trim(),
    when,
    steps,
    verify,
    scope: scope === 'workspace' || scope === 'global' ? scope : 'project',
    scene: /^[a-z][a-z0-9-]{1,23}$/u.test(scene) ? scene : 'general',
    domain: /^[a-z][a-z0-9-]{1,31}$/u.test(String((raw       ).domain ?? '').trim().toLowerCase())
      ? String((raw       ).domain).trim().toLowerCase()
      : 'general',
    aliases,
    ...(tags.length === 0 ? {} : { tags }),
    ...(applicableNodeTypes.length === 0 ? {} : { applicableNodeTypes }),
    confidence: clampConfidence((raw       ).confidence),
    evidence,
  }
}

/**
 * The shared vocabulary grammar, duplicated from `knowledge.ts` on purpose.
 *
 * `store.ts` is imported by `knowledge.ts`, so importing back would be a cycle. The grammar is a
 * regex and a dedupe loop; the alternative — a cycle in a package that strips types at build time,
 * where a cycle is a load-order bug rather than a linked warning — is decidedly worse.
 */
const VOCAB_TAG = /^[a-z0-9][a-z0-9+#._-]{0,31}$/u

/** Normalise a tag / node-type list: lowercase, hyphenated, validated, deduped, capped. */
export function asVocab(value         , max = 8)           {
  const raw = Array.isArray(value) ? value : typeof value === 'string' ? value.split(/[,\s]+/u) : []
  const out           = []
  for (const item of raw) {
    if (typeof item !== 'string') continue
    const tag = item.trim().toLowerCase().replace(/\s+/gu, '-')
    if (!VOCAB_TAG.test(tag) || out.includes(tag)) continue
    out.push(tag)
    if (out.length >= max) break
  }
  return out
}

/** v0.7.1: a feedback weight, kept in [0.2, 1.0]; a missing field is full trust. */
export function clampConfidence(value         )         {
  const number = Number(value)
  if (!Number.isFinite(number)) return 1
  return Math.min(1, Math.max(0.2, Math.round(number * 100) / 100))
}

/**
 * Words that describe the shared *purpose* and therefore must not be the only
 * reason two skills are called conflicting. "Python" and "连接数据库" appear in
 * every database skill; the conflict is pymysql-versus-sqlite3, not the verb.
 */
const PURPOSE_NOISE = new Set([
  'python', 'py', 'code', 'script', '简单', '一个', '使用', '实现', '封装', '方法', '步骤', '测试', '操作',
  // v0.3.1: TESTING vocabulary was the false-positive engine. Measured on the
  // battle store: "阈值样本设计" and "SQLite 封装测试" shared 验证/真实/用例/覆盖
  // and were cross-linked as alternatives, which is nonsense — they are not the
  // same decision. The distinguishing token has to be about the SUBJECT, not
  // about how the subject was checked.
  '验证', '断言', '真实', '回归', '覆盖', '失败', '通过', '用例', '轮次', '重复',
  '编写', '调用', '打开', '读取', '返回', '记录', '结果', '情况', '保证', '确认',
])

function purposeTokens(skill                                       )              {
  const text = `${skill.description} ${skill.when}`.toLowerCase()
  const out = new Set        ()
  for (const match of text.matchAll(/[a-z0-9][a-z0-9_-]{1,}/gu)) out.add(match[0])
  for (const run of text.match(/\p{Script=Han}+/gu) ?? []) {
    if (run.length === 1) out.add(run)
    for (let index = 0; index + 2 <= run.length; index += 1) out.add(run.slice(index, index + 2))
  }
  for (const token of PURPOSE_NOISE) out.delete(token)
  return out
}

function sharedPurpose(a                , b                )         {
  const left = purposeTokens(a)
  const right = purposeTokens(b)
  let shared = 0
  for (const token of left) if (right.has(token)) shared += 1
  return shared
}

/**
 * v1.0.0 P0 — METHOD SIMILARITY IS A PROPERTY OF THE STEPS, NOT OF THE PROSE AROUND THEM.
 *
 * THE BUG THIS FIXES (measured, not theorised)
 *
 * This used to be `jaccard(trigrams(description + steps), …)`. Putting a free-form
 * `description` into the same trigram set as the procedure body made the score MOVE with
 * the description's LENGTH and with the shape of its numbers, and the whole conflict
 * decision hangs off a hard 0.85 threshold. Measured on the audit's own fixture, where
 * every skill's steps were byte-identical and only the index differed:
 *
 *     …技能 100  vs …技能 101   → 0.9077  → "same method"  ✅
 *     …技能 999  vs …技能 1000  → 0.8382  → "different method" ❌ WRONG
 *     …技能 1234 vs …技能 8765  → 0.8261  → "different method" ❌ WRONG
 *
 * Out of 15 sampled pairs, 6 were declared conflicting DESPITE having the same steps —
 * 15 pairs, identical procedures, "these are mutually exclusive alternatives, pick one".
 *
 * The values were not continuous either: across 899 pairs one skill only ever scored
 * 0.846, 0.875 or 0.905. A metric that produces three values on one input family and
 * decides a binary question at a boundary is measuring the FIXTURE, not the method.
 *
 * WHAT IT IS NOW
 *
 * Only the EXECUTION STEPS are compared. Two procedures with the same steps are the same
 * method however differently they are described — that is what "method" means. The
 * description still matters for *purpose* (`purposeTokens`/`conflictStrength`), which is
 * where it belongs: purpose decides whether two skills are about the same thing at all.
 *
 * WHAT THIS DELIBERATELY DOES NOT DO
 *
 * It does not normalise digits away. Stripping digits here would be the same error as the
 * `normalizeForMatch` bug fixed earlier today, one floor up: `端口 3000` and `端口 8080`
 * have genuinely different steps. Digits inside the STEPS are evidence; digits inside a
 * NAME are noise. That distinction is the whole fix.
 */
function methodSimilarity(a                , b                )         {
  /**
   * A skill with no parsable steps cannot be compared on method. Returning 0 here is the
   * conservative direction: "unknown method" must not silently become "same method" and
   * suppress a real conflict. `writeSkill` refuses step-less skills anyway, so this only
   * affects skills written by older versions or by hand.
   */
  const leftSteps = a.steps.map((step) => step.trim()).filter(Boolean)
  const rightSteps = b.steps.map((step) => step.trim()).filter(Boolean)
  if (leftSteps.length === 0 || rightSteps.length === 0) return 0
  return jaccard(trigrams(leftSteps.join(' ')), trigrams(rightSteps.join(' ')))
}

/**
 * Two skills conflict when they address the same PURPOSE with a DIFFERENT
 * METHOD.
 *
 * v0.3: measured need. A session that learns "connect MySQL with pymysql" and a
 * session that learns "connect SQLite with sqlite3" produce two procedures with
 * nearly the same trigger and almost no shared steps. Storing both silently is
 * what makes a later retrieval ambiguous: the hint says "this worked last time"
 * twice, for two mutually exclusive answers. They are not duplicates (neither
 * name nor steps match), and they are not unrelated either — they are
 * alternatives, and the record has to say so.
 */
                                
              
               
 

/**
 * v0.3.1: recompute every conflict edge from the current rules.
 * v1.0.0 P0: recompute into the EDGE INDEX, and do not touch SKILL.md at all.
 *
 * Needed because edges are written incrementally: a rule change (a looser earlier rule, or
 * the v1.0.0 fix to `methodSimilarity`) leaves edges in the index that no future write
 * would ever remove. The old implementation stripped `conflicts_with` and the warning
 * section out of each file and re-linked pairwise — one full rewrite per skill, then one
 * more per discovered edge, which is the same quadratic shape this release removes.
 *
 * Now: read every shape once, compute the true pair set, and REPLACE the index in one
 * write. The files are not modified, because they no longer contain edges to strip. A
 * legacy store keeps its stale inline copies; `retrieve` merges them with the index, so the
 * stale ones simply stop appearing once the file is rewritten for any other reason.
 */
export function rebuildConflictLinks(skillsDir        )                                  {
  const skills                   = []
  for (const name of listSkillFiles(skillsDir)) {
    const path = skillPath(skillsDir, name)
    if (!existsSync(path)) continue
    try {
      skills.push(parseSkillFile(readFileSync(path, 'utf8'), name))
    } catch {
      // A broken file is skipped, not rewritten.
    }
  }
  const pairs                                  = []
  for (let leftIndex = 0; leftIndex < skills.length; leftIndex += 1) {
    for (let rightIndex = leftIndex + 1; rightIndex < skills.length; rightIndex += 1) {
      if (!isConflictingSkill(skills[leftIndex], skills[rightIndex])) continue
      pairs.push({ a: skills[leftIndex].name, b: skills[rightIndex].name })
    }
  }
  replaceEdges(
    skillsDir,
    pairs.map((pair) => [pair.a, pair.b]         ),
  )
  return pairs
}

export function conflictStrength(a                , b                )                                                              {
  const left = purposeTokens(a)
  const right = purposeTokens(b)
  const shared           = []
  for (const token of left) if (right.has(token)) shared.push(token)
  return {
    shared: shared.length,
    onlyLeft: [...left].filter((token) => !right.has(token)),
    onlyRight: [...right].filter((token) => !left.has(token)),
  }
}

export function isConflictingSkill(a                , b                )          {
  if (a.name === b.name) return true
  /**
   * v1.0.0 P0: "same name is a conflict" is the ONLY conclusion available when neither
   * skill has a parsable procedure. Without this guard, `methodSimilarity` returns 0 for
   * an empty step list — which reads as "completely different method" — and two step-less
   * records that merely share some purpose words get linked as alternatives. Measured
   * while fixing this: two skills with `steps: []` returned TRUE. That is the same
   * "unknown silently becomes a claim" failure the rest of this function is careful about.
   */
  const leftSteps = a.steps.map((step) => step.trim()).filter(Boolean)
  const rightSteps = b.steps.map((step) => step.trim()).filter(Boolean)
  if (leftSteps.length === 0 || rightSteps.length === 0) return false
  // Two names for the same steps is a duplicate, not a conflict.
  if (methodSimilarity(a, b) >= 0.85) return false
  /**
   * v0.17: `scene` is the technology, `domain` is the SYSTEM. Two procedures about
   * different systems are not two ways of doing one thing, however similar their
   * wording — linking them asked the user to choose between unrelated methods.
   *
   * NOTE: this block used to appear TWICE, identically. Deleting the copy is safe (both
   * returned the same value), and it is worth recording because a duplicated guard is a
   * guard that will eventually be edited in one place only.
   */
  if (
    a.domain !== undefined &&
    b.domain !== undefined &&
    a.domain !== 'general' &&
    b.domain !== 'general' &&
    a.domain !== b.domain
  ) {
    return false
  }
  const { shared, onlyLeft, onlyRight } = conflictStrength(a, b)
  // v0.3.2: measured on the battle store. 3 shared bigrams linked 25 pairs out of
  // 16 skills — the DB cluster alone produced a complete graph, which is noise,
  // not knowledge. 5 keeps the genuine alternative (two SAVEPOINT stacks for two
  // different drivers) and drops "both mention transactions somewhere".
  if (shared < 3) return false
  return onlyLeft.length > 0 && onlyRight.length > 0
}

/** Read the executable shape back out of one SKILL.md (enough to compare). */
export function parseSkillFile(text        , name        )                 {
  const when = text.match(/^when_to_use:\s*(.+)$/mu)?.[1] ?? text.match(/^when:\s*(.+)$/mu)?.[1] ?? ''
  const description = text.match(/^description:\s*(.+)$/mu)?.[1] ?? when
  const title = text.match(/^#\s+(.+)$/mu)?.[1] ?? name
  const steps           = []
  const body = text.replace(/^---[\s\S]*?---/u, '')
  const stepBlock = body.split(/^## 执行步骤$/mu)[1]?.split(/^## /mu)[0] ?? ''
  for (const line of stepBlock.split(/\r?\n/u)) {
    const match = /^\s*\d+\.\s+(.+)$/u.exec(line)
    if (match !== null) steps.push(match[1].trim())
  }
  const evidence = parseEvidenceField(text.match(/^evidence:\s*(.+)$/mu)?.[1] ?? '', '')
  const scopeText = (text.match(/^scope:\s*(.+)$/mu)?.[1] ?? '').trim().toLowerCase()
  const sceneText = (text.match(/^scene:\s*(.+)$/mu)?.[1] ?? '').trim().toLowerCase()
  const domainText = (text.match(/^domain:\s*(.+)$/mu)?.[1] ?? '').trim().toLowerCase()
  const confidence = clampConfidence(text.match(/^confidence:\s*(.+)$/mu)?.[1])
  const aliases = (text.match(/^aliases:\s*(.+)$/mu)?.[1] ?? '').split(/,/u).map((item) => item.trim()).filter(Boolean)
  return {
    name,
    title,
    description,
    when,
    steps,
    verify: [],
    scope: scopeText === 'workspace' || scopeText === 'global' ? scopeText : 'project',
    scene: /^[a-z][a-z0-9-]{1,23}$/u.test(sceneText) ? sceneText : 'general',
    domain: /^[a-z][a-z0-9-]{1,31}$/u.test(domainText) ? domainText : 'general',
    aliases,
    ...(() => {
      const tags = asVocab(text.match(/^tags:\s*(.+)$/mu)?.[1] ?? '')
      return tags.length === 0 ? {} : { tags }
    })(),
    ...(() => {
      const nodeTypes = asVocab(text.match(/^applicable_node_types:\s*(.+)$/mu)?.[1] ?? '')
      return nodeTypes.length === 0 ? {} : { applicableNodeTypes: nodeTypes }
    })(),
    confidence,
    evidence,
  }
}

function listSkillFiles(skillsDir        )           {
  try {
    return readdirSync(skillsDir, { withFileTypes: true })
      .filter((entry) => entry.isDirectory())
      .map((entry) => entry.name)
  } catch {
    return []
  }
}

/**
 * v1.0.0 P0 — CONFLICT DISCOVERY IS A READ; ONLY THE EDGE WRITE HAD TO CHANGE.
 *
 * `findConflicts` must SCAN every existing skill: a conflict is a property of two shapes,
 * and a shape that was never written down cannot be looked up in an index. The first
 * version of this refactor made discovery read the edge index instead — which is a
 * chicken-and-egg bug: the index only contains edges that discovery already found, so the
 * very first conflict could never be recorded. Caught by a 5-skill fixture producing an
 * empty `skills-edges.jsonl`.
 *
 * v1.0.0 P0 C: THE SCAN IS CACHED PER (dir, name, mtime, size).
 *
 * Rewriting a growing file per edge was the O(N²) IO. What was left after that fix is a
 * smaller but still quadratic cost: writing N skills in one process re-reads and re-parses
 * every earlier skill N times. Measured after the join fix: 7.0 ms/skill at N=50 rising to
 * 23.0 ms/skill at N=200 (3.28×). The cache below turns those re-parses into map lookups.
 *
 * INVALIDATION IS BY stat, NOT BY TRUST: a cached shape is reused only when mtime AND size
 * both match. Another process editing a SKILL.md therefore cannot leave a stale shape in
 * play — which matters because harvest writes are one process and reviews are another.
 */
                       
                 
              
                       
 

const shapeCache = new Map                                  ()

/** Drop the cached shape of one skill (after this process writes it). */
export function invalidateSkillShape(skillsDir        , name        )       {
  shapeCache.get(skillsDir)?.delete(name)
}

/** Drop every cached shape for a directory. Tests and bulk rebuilds call this. */
export function clearSkillShapeCache(skillsDir         )       {
  if (skillsDir === undefined) shapeCache.clear()
  else shapeCache.delete(skillsDir)
}

function shapeOf(skillsDir        , name        )                             {
  const path = skillPath(skillsDir, name)
  let stat                                   
  try {
    stat = statSync(path)
  } catch {
    shapeCache.get(skillsDir)?.delete(name)
    return undefined
  }
  const bucket = shapeCache.get(skillsDir) ?? new Map                     ()
  if (!shapeCache.has(skillsDir)) shapeCache.set(skillsDir, bucket)
  const cached = bucket.get(name)
  if (cached !== undefined && cached.mtimeMs === stat.mtimeMs && cached.size === stat.size) return cached.skill
  let text        
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    return undefined
  }
  const skill = parseSkillFile(text, name)
  bucket.set(name, { mtimeMs: stat.mtimeMs, size: stat.size, skill })
  return skill
}

export function findConflicts(skillsDir        , skill                )                  {
  const out                  = []
  for (const name of listSkillFiles(skillsDir)) {
    if (name === skill.name) continue
    const other = shapeOf(skillsDir, name)
    if (other === undefined) continue
    if (isConflictingSkill(skill, other)) out.push({ name, title: other.title })
  }
  return out
}

function conflictFooter(conflicts                          )           {
  if (conflicts.length === 0) return []
  return [
    '',
    '## ⚠️ 冲突提示',
    '',
    ...conflicts.map(
      (conflict) => `- 与 \`${conflict.name}\`（${conflict.title}）用途相近但方法不同，选用前先确认场景，不要混用。`,
    ),
    '',
  ]
}
  function parseEvidenceField(raw        , fallbackSession        )                {
  const refs                = []
  for (const token of raw.split(/[,\s]+/u).filter(Boolean)) {
    const at = token.lastIndexOf('@')
    const sourceSessionId = at > 0 ? token.slice(0, at) : fallbackSession
    const seq = Number(at > 0 ? token.slice(at + 1) : token)
    if (!Number.isFinite(seq)) continue
    if (refs.some((ref) => ref.seq === seq && ref.sourceSessionId === sourceSessionId)) continue
    refs.push({ sourceSessionId, seq })
  }
  return refs
}

function evidenceBodyLines(evidence                        , fallbackSession        )           {
  const bySession = new Map                  ()
  for (const ref of evidence) {
    const session = ref.sourceSessionId.length > 0 ? ref.sourceSessionId : fallbackSession
    const list = bySession.get(session) ?? []
    list.push(ref.seq)
    bySession.set(session, list)
  }
  return [...bySession.entries()].map(([session, seqs]) => `- 源会话：${session}（seq ${seqs.join(', ')}）`)
}

function renderSkill(
  skill                ,
  meta           ,
  previous    
                    
                   
                   
                     
                          
                    
                      
                         
                         
                       
   ,
  conflicts                           = [],
)         {
  const now = meta.at ?? new Date().toISOString().slice(0, 10)
  const workspace = normalizeWorkspace(meta.workspace)
  const fields                                  = {
    name: skill.name,
    description: skill.description.slice(0, 160),
    when_to_use: skill.when.slice(0, 200),
    scope: skill.scope,
    /**
     * NOTE the single `domain` key. This literal previously declared it TWICE in a row — the second silently
     * won. It happened to be identical, so nothing ever failed, which is exactly why it survived: the bug was
     * invisible until the day someone edited only one of them.
     */
    domain: skill.domain ?? 'general',
    /**
     * v0.32 — THE CAUSAL FIELDS, WRITTEN ONLY WHEN THE CALLER ACTUALLY KNOWS THEM.
     *
     * `dependencies` and `target_effect` are what turn a skill from a procedure into a MACRO: preconditions
     * in, expected state out. They are omitted rather than defaulted, because an invented precondition would
     * be read back by `causalChain` as evidence and would make a chain look complete when it is not.
     */
    ...(Array.isArray((skill                  ).dependencies) && (skill                  ).dependencies .length > 0
      ? {
          dependencies: (skill                  )
            .dependencies .map((ref) => (ref.sourceSessionId.length > 0 ? `${ref.sourceSessionId}@${ref.seq}` : String(ref.seq)))
            .join(','),
        }
      : {}),
    ...(typeof (skill                  ).target_effect === 'string' &&
    ((skill                  ).target_effect          ).length > 0
      ? { target_effect: (skill                  ).target_effect           }
      : {}),
    // v0.8: provenance for the isolation gate (see workspace.ts). Written even for
    // a `global` skill: `global` decides ELIGIBILITY, the path stays on record for
    // audit. Omitted only when the caller genuinely had no workspace.
    ...(workspace.length === 0 ? {} : { workspace }),
    scene: skill.scene,
    ...(skill.aliases.length === 0 ? {} : { aliases: skill.aliases.join(', ') }),
    /**
     * GLOBAL KNOWLEDGE BASE — WRITTEN ONLY WHEN THE CALLER NAMED THEM.
     *
     * Same rule as `dependencies`: an invented tag would make a local memory look shareable, and
     * a reader in another workspace would then trust it as a general rule. An omitted field reads
     * back as "no cross-workspace reach", which is exactly the pre-existing behaviour.
     */
    ...(() => {
      const tags = asVocab((skill                  ).tags)
      return tags.length === 0 ? {} : { tags: tags.join(', ') }
    })(),
    ...(() => {
      const nodeTypes = asVocab((skill                  ).applicableNodeTypes)
      return nodeTypes.length === 0 ? {} : { applicable_node_types: nodeTypes.join(', ') }
    })(),
    confidence: clampConfidence(skill.confidence).toFixed(2),
    evidence: skill.evidence
      .map((ref) => (ref.sourceSessionId.length > 0 ? `${ref.sourceSessionId}@${ref.seq}` : String(ref.seq)))
      .join(','),
    sources: previous === undefined ? 1 : previous.sources,
    /**
     * v1.0.0 P0 — NO INLINE CONFLICT EDGES.
     *
     * This used to emit `conflicts_with: a,b,c,…` here, and `reorder` below emitted the
     * same neighbors again as prose under `## ⚠️ 冲突提示`. Both are gone. Every edge now
     * lives in `skills-edges.jsonl` (see edges.ts), joined at retrieval time.
     *
     * WHY REMOVE IT RATHER THAN CAP IT: the field was a single line that grew with every
     * neighbor, so one file reached 12,959 characters of names plus 91 KB of repeated
     * prose. Retrieval had to read and tokenize all of it to answer a question about the
     * skill's trigger. Capping the line would have kept both costs and added a truncation
     * bug. The edge is a GRAPH FACT, not a property of one file.
     *
     * A legacy store still has the field on disk; `migrateLegacyEdges` folds those into the
     * index and nothing rewrites the files (a stale hint is harmless; a mass rewrite is not).
     */
  }
  if (previous !== undefined && previous.created.length > 0) {
    fields.created = previous.created
    fields.updated = now
  } else {
    fields.created = now
  }
  // v0.15 bi-temporal + trust fields.
  //
  // `valid_at` defaults to the write time; `invalid_at` is written ONLY when the
  // record has actually been superseded (an empty field on every skill would make
  // "active" and "never validated" indistinguishable in a grep). A merge keeps the
  // ORIGINAL valid_at and an existing invalidation: refreshing the wording of a
  // superseded rule must not quietly resurrect it.
  fields.valid_at = previous?.validAt !== undefined && previous.validAt.length > 0 ? previous.validAt : now
  if (previous?.invalidAt !== undefined && previous.invalidAt.length > 0) fields.invalid_at = previous.invalidAt
  if (previous?.supersededBy !== undefined && previous.supersededBy.length > 0) fields.superseded_by = previous.supersededBy
  if (previous?.supersedes !== undefined && previous.supersedes.length > 0) fields.supersedes = previous.supersedes.join(',')
  fields.provenance = previous?.provenance !== undefined && previous.provenance.length > 0 ? previous.provenance : meta.provenance ?? 'inferred'
  /**
   * v0.32 P1: the generation and the commit the experience belongs to. Written only when
   * the caller actually knows them — an invented commit would be worse than no commit,
   * because retrieval treats a mismatch as "this is old" and a missing value as "unknown".
   */
  if (typeof meta.generation === 'number' && Number.isFinite(meta.generation) && meta.generation > 0) {
    fields.generation = Math.trunc(meta.generation)
  }
  if (typeof meta.commitHash === 'string' && /^[0-9a-f]{7,40}$/u.test(meta.commitHash)) {
    fields.commitHash = meta.commitHash
  }
  // v0.5 decay bookkeeping: a fresh write is also a fresh validation.
  fields.last_validated = previous?.lastValidated !== undefined && previous.lastValidated.length > 0 ? previous.lastValidated : now
  fields.last_used = previous?.lastUsed !== undefined && previous.lastUsed.length > 0 ? previous.lastUsed : now
  return [
    frontmatter(fields),
    '',
    `# ${skill.title}`,
    '',
    '## 何时使用',
    '',
    skill.when,
    '',
    '## 执行步骤',
    '',
    ...skill.steps.map((step, index) => `${index + 1}. ${step}`),
    '',
    '## 验证标准',
    '',
    ...skill.verify.map((line) => `- ${line}`),
    '',
    '## 证据',
    '',
    ...evidenceBodyLines(skill.evidence, meta.sessionId),
    /**
     * v1.0.0 P0 — the `## ⚠️ 冲突提示` footer is GONE.
     *
     * It repeated up to 720 neighbor names as prose inside the skill file, which is what
     * made a 798 B skill grow to 104 KB and forced retrieval to read 91 KB of warnings to
     * answer a query about the trigger. Conflicts are now joined from `skills-edges.jsonl`
     * where they are actually needed — see retrieve.ts. `conflictFooter` is kept exported
     * below for the render of a HUMAN-facing listing, never for the stored file.
     */
  ].join('\n')
}

/**
 * v0.7.1: environment/version tokens that make two procedures NOT interchangeable.
 *
 * The failure this guards: "install pymysql on Python 3.8" and "use the stdlib
 * driver on Python 3.12" share a trigger and both connect to MySQL, so the
 * similarity gate merged them into one file — and the merged procedure ran on
 * neither version. A version difference is evidence of an alternative, not of a
 * synonym.
 */
const VERSION_TOKEN = /\b(python|py|node|nodejs|go|golang|java|rust|ruby|php|deno|bun|typescript|ts|dotnet|net)[\s_-]?v?(\d+(?:\.\d+)+)/giu
const ENVIRONMENT_TOKEN = /\b(windows|win32|linux|ubuntu|debian|centos|macos|darwin|wsl|docker|alpine|arm64|x86[_-]?64|amd64)\b/giu

export function environmentTokensOf(text        )              {
  const out = new Set        ()
  for (const match of text.toLowerCase().matchAll(VERSION_TOKEN)) {
    const runtime = match[1] === 'py' ? 'python' : match[1] === 'nodejs' ? 'node' : match[1]
    out.add(`${runtime}${match[2]}`)
  }
  for (const match of text.toLowerCase().matchAll(ENVIRONMENT_TOKEN)) out.add(match[1].replace(/[_-]/gu, ''))
  return out
}

function triggerTokens(text        )              {
  const out = new Set        ()
  const lower = text.toLowerCase()
  for (const match of lower.matchAll(/[a-z0-9][a-z0-9_-]{1,}/gu)) out.add(match[0])
  for (const run of lower.match(/\p{Script=Han}+/gu) ?? []) {
    if (run.length === 1) out.add(run)
    for (let index = 0; index + 2 <= run.length; index += 1) out.add(run.slice(index, index + 2))
  }
  return out
}

function triggerSimilarity(left        , right        )         {
  const a = triggerTokens(left)
  const b = triggerTokens(right)
  if (a.size === 0 || b.size === 0) return 0
  let shared = 0
  for (const token of a) if (b.has(token)) shared += 1
  return shared / Math.min(a.size, b.size)
}

                                        
                    
                
 

/**
 * v0.7.1: same purpose, different named environment → DO NOT MERGE.
 * Returns the two token sets when merging would erase a real difference.
 */
export function environmentDivergence(previous                , next                )                                    {
  const left = environmentTokensOf(`${previous.when} ${previous.steps.join(' ')}`)
  const right = environmentTokensOf(`${next.when} ${next.steps.join(' ')}`)
  if (left.size === 0 || right.size === 0) return undefined
  // A shared runtime token means the procedures agree on the environment.
  for (const token of left) if (right.has(token)) return undefined
  if (triggerSimilarity(previous.when, next.when) < 0.5) return undefined
  return { previous: [...left].slice(0, 4), next: [...right].slice(0, 4) }
}

/** A free kebab-case name, so a divergence keeps BOTH procedures on disk. */
function uniqueSkillName(skillsDir        , base        )         {
  for (let index = 2; index < 100; index += 1) {
    const candidate = `${base}-${index}`
    if (candidate.length > 48) break
    if (!existsSync(skillPath(skillsDir, candidate))) return candidate
  }
  return `${base}-${Date.now().toString(36)}`.slice(0, 48)
}

/** Create or merge one skill. Returns `created`, `merged`, `conflicted:<env>` or `skipped:<reason>`. */
export function writeSkill(skillsDir        , input                             , meta           )         {
  const skill = normalizeSkill(input)
  if (skill.steps.length === 0) return 'skipped:no execution steps'
  if (skill.verify.length === 0) return 'skipped:no verification criterion'
  // v0.6: a ref without a session id inherits the session that produced it.
  const withSession                 = {
    ...skill,
    evidence: skill.evidence.map((ref) => ({ ...ref, sourceSessionId: ref.sourceSessionId.length > 0 ? ref.sourceSessionId : meta.sessionId })),
    /**
     * v0.32 — CARRY THE CAUSAL FIELDS THROUGH THE NORMALIZER.
     *
     * `normalizeSkill` rebuilds the record from a known set of fields, so anything it does not name is
     * dropped. `dependencies` / `target_effect` were added to the schema but not to that whitelist, and the
     * effect was silent: the skill was written, `readSkillBody` returned no preconditions, and the causal
     * chain looked complete while missing its first hop. Copying them explicitly here (and pointing each
     * dependency at the fallback session) is what makes the round trip whole.
     */
    ...(Array.isArray((input                  ).dependencies)
      ? {
          dependencies: (input                  ).dependencies .map((ref) => ({
            ...ref,
            sourceSessionId: ref.sourceSessionId.length > 0 ? ref.sourceSessionId : meta.sessionId,
          })),
        }
      : {}),
    ...(typeof (input                  ).target_effect === 'string'
      ? { target_effect: (input                  ).target_effect }
      : {}),
  }
  const threat = scanThreat(`${skill.title} ${skill.description} ${skill.when} ${skill.steps.join(' ')} ${skill.verify.join(' ')}`)
  if (threat !== undefined) return `skipped:${threat}`
  // v0.3: record mutually exclusive alternatives instead of storing both silently.
  const conflicts = findConflicts(skillsDir, skill)
  const path = skillPath(skillsDir, skill.name)
  if (existsSync(path)) {
    // Merge: keep the earliest evidence, refresh the wording, count the use of
    // the *provenance* (sessions that confirmed it), never duplicate the file.
    const previousText = readFileSync(path, 'utf8')
    // v0.8: a write with no workspace (a queued suggestion replayed later, an
    // older caller) inherits the workspace already recorded. Otherwise a merge
    // would silently launder a memory out of the workspace that produced it.
    const previousWorkspace = readSkillWorkspace(previousText)
    const writeMeta            =
      normalizeWorkspace(meta.workspace).length > 0 || previousWorkspace.length === 0
        ? meta
        : { ...meta, workspace: previousWorkspace }
    // v0.7.1: a version/environment difference is a CONFLICT, never a merge.
    const previousSkill = parseSkillFile(previousText, skill.name)
    const divergence = environmentDivergence(previousSkill, skill)
    if (divergence !== undefined) {
      const altName = uniqueSkillName(skillsDir, skill.name)
      const conflict                = { name: skill.name, title: previousSkill.title }
      const alternative                 = { ...withSession, name: altName, confidence: 1 }
      atomicWrite(skillPath(skillsDir, altName), renderSkill(alternative, writeMeta, undefined, [conflict]))
      linkConflictBack(skillsDir, conflict, alternative)
      return `conflicted:${divergence.previous.join(',')} vs ${divergence.next.join(',')}`
    }
    const previousEvidence = parseEvidenceField(previousText.match(/^evidence:\s*(.+)$/mu)?.[1] ?? '', meta.sessionId)
    const previousValidity = readSkillValidity(previousText)
    const evidenceKey = (ref             )         => `${ref.sourceSessionId}@${ref.seq}`
    const merged = [...new Map([...previousEvidence, ...withSession.evidence].map((ref) => [evidenceKey(ref), ref])).values()]
    const sources = Number(previousText.match(/^sources:\s*(\d+)$/mu)?.[1] ?? '1')
    const created = previousText.match(/^created:\s*(.+)$/mu)?.[1] ?? ''
    const lastUsed = previousText.match(/^last_used:\s*(.+)$/mu)?.[1] ?? undefined
    const lastValidated = previousText.match(/^last_validated:\s*(.+)$/mu)?.[1] ?? undefined
    // v0.7.1: repetition must not launder a skill that failed in use; keep the
    // learned confidence across the merge.
    const mergedSkill                 = { ...withSession, evidence: merged, confidence: clampConfidence(previousSkill.confidence) }
    atomicWrite(path, renderSkill(mergedSkill, writeMeta, { evidence: merged.length, sources: sources + 1, created, lastUsed, lastValidated, validAt: previousValidity.validAt, invalidAt: previousValidity.invalidAt, supersededBy: previousValidity.supersededBy, supersedes: previousValidity.supersedes, provenance: previousValidity.provenance }, conflicts))
    commitEdges(skillsDir, skill.name, conflicts)
    invalidateSkillShape(skillsDir, skill.name)
    /** v1.1.0: the retrieval-side document cache must not serve the pre-write shape. */
    invalidateSkillDocs(skillsDir)
    return 'merged'
  }
  atomicWrite(path, renderSkill(withSession, meta, undefined, conflicts))
  commitEdges(skillsDir, skill.name, conflicts)
  invalidateSkillShape(skillsDir, skill.name)
  invalidateSkillDocs(skillsDir)
  return 'created'
}

/**
 * v1.0.0 P0 C — ONE APPEND FOR ALL OF A SKILL'S EDGES.
 *
 * The loop this replaces called `linkConflictBack` once per neighbor, and each call wrote
 * the index separately. A skill with 300 true conflicts meant 300 open/append/close cycles
 * for one write. Batching turns that into a single append; the edge count itself is a
 * property of the store's content and cannot be reduced (and must not be — a real conflict
 * is information).
 */
function commitEdges(skillsDir        , name        , conflicts                          )       {
  if (conflicts.length === 0) return
  writeEdges(
    skillsDir,
    conflicts.map((conflict) => [name, conflict.name]         ),
  )
}

/**
 * v1.0.0 P0 — CONFLICT INDEX LAYER: EDGE WRITING
 *
 * Instead of rewriting the whole SKILL.md file, we just append one line to the shared index.
 * The old code path (line 911–936) did a full read/write for each edge. That is now
 * replaced with an O(1) append-only write. Backwards compatibility: legacy files that
 * already carry conflicts_with will be migrated by runMigration().
 */
export function linkConflictBack(skillsDir        , target               , other                                 )       {
  /** Write edge only — no more rewrites of individual SKILL.md files. */
  writeEdge(skillsDir, target.name, other.name)
}

/**
 * v0.15: append one auditable decision line.
 *
 * Why a file and not a log line: the supersede decision is made by a MODEL during
 * retrieval, and it changes what future sessions believe. "Which memory was
 * invalidated, by whom, on what grounds, and when" has to survive the process that
 * made the decision — including a refused decision, which is the more interesting
 * half (it means a guard fired).
 */
                                   
            
                                         
                 
                
                 
                 
                
                 
 

export function memoryAuditPath(memoryDir        )         {
  return join(memoryDir, '.memory-audit.jsonl')
}

/**
 * v1.0.0 P0 — THE AUDIT LEDGER IS EVIDENCE, BUT EVIDENCE NEEDS A SHELF.
 *
 * The audit flagged `.memory-audit.jsonl` as unbounded with no rotation, and the old
 * implementation was worse than "append-only": it did `readFileSync` + `atomicWrite` — a
 * full read and a full rewrite per line. So the Nth audit entry cost O(N) IO, and the file
 * was carried in memory on every append. A long-lived profile pays that forever.
 *
 * ROTATION POLICY: archive, never delete.
 *
 * An audit trail whose oldest entries are silently dropped is not an audit trail. So when
 * the active file passes `AUDIT_ROTATE_BYTES`, it is RENAMED to a timestamped sibling and a
 * fresh active file starts. The most recent `AUDIT_KEEP` archives are retained; older ones
 * are removed because at that point the storage cost is the thing being managed. If the
 * rename fails, the append still happens to the active file — an audit write must never
 * lose the line it was asked to record.
 */
export const AUDIT_ROTATE_BYTES = 4 * 1024 * 1024
export const AUDIT_KEEP = 3

/** Rotate `path` when it has grown past `limitBytes`. Returns the archive name, or undefined. */
export function rotateAuditIfNeeded(path        , limitBytes = AUDIT_ROTATE_BYTES, keep = AUDIT_KEEP)                     {
  let size = 0
  try {
    size = statSync(path).size
  } catch {
    return undefined
  }
  if (size < limitBytes) return undefined
  const dir = dirname(path)
  const base = path.slice(dir.length + 1)
  const stamp = new Date().toISOString().replace(/[:.]/gu, '-')
  const archive = join(dir, `${base}.${stamp}`)
  try {
    renameSync(path, archive)
  } catch {
    return undefined
  }
  /**
   * Prune old archives. Sorted by name, which sorts by ISO timestamp — no mtime parsing.
   * A failure here is ignored: a leftover archive costs disk, not correctness.
   */
  try {
    const prefix = `${base}.`
    const archives = readdirSync(dir)
      .filter((name) => name.startsWith(prefix))
      .sort()
    for (const name of archives.slice(0, Math.max(0, archives.length - keep))) {
      try {
        rmSync(join(dir, name), { force: true })
      } catch {
        /* a stuck archive is not worth failing the append */
      }
    }
  } catch {
    /* ignore */
  }
  return archive
}

export function appendMemoryAudit(memoryDir        , entry                  )       {
  try {
    mkdirSync(memoryDir, { recursive: true })
    const path = memoryAuditPath(memoryDir)
    /**
     * APPEND, not read-all-rewrite. The previous version read the whole ledger and wrote it
     * back with one more line, which made the Nth entry cost O(N) IO. `appendFileSync` is
     * the operation the file's name always implied.
     *
     * Rotation runs BEFORE the append so a single append can never be split across the
     * rotate boundary — the line lands wholly in one file.
     */
    rotateAuditIfNeeded(path)
    appendFileSync(path, `${JSON.stringify(entry)}\n`, 'utf8')
  } catch {
    // Audit is evidence, never a gate: a failed line must not change the outcome.
  }
}

                                    
                
               
                
                                                
 

                                  
                  
                
                    
 

/**
 * v0.15: invalidate an old memory in favour of a new one.
 *
 * The old record is NOT deleted. It gets `invalid_at` (the successor's valid_at),
 * `superseded_by`, and a footer that says why; the successor gets the reverse
 * `supersedes` link. Retrieval then stops activating the old one by the ordinary
 * validity rule, so there is exactly one gate, not two.
 *
 * The human guard lives HERE, not only in the prompt: an inference may not
 * invalidate what a human stated. A prompt rule is a request; this is the refusal.
 */
export function applySupersede(
  memoryDir        ,
  skillsDir        ,
  decision                   ,
  options                                  = {},
)                  {
  const winner = String(decision.winner ?? '').trim()
  const loser = String(decision.loser ?? '').trim()
  const at = options.at ?? new Date().toISOString()
  const audit = (kind                          , extra                            = {})       => {
    appendMemoryAudit(memoryDir, {
      at,
      kind,
      winner,
      loser,
      reason: decision.reason,
      ...(options.query === undefined ? {} : { query: options.query.slice(0, 200) }),
      source: 'llm-filter',
      ...extra,
    })
  }
  if (winner.length === 0 || loser.length === 0 || winner === loser) {
    audit('supersede-refused', { detail: 'winner and loser must be two different skills' })
    return { applied: false, status: 'refused:winner-or-loser-invalid' }
  }
  const winnerPath = skillPath(skillsDir, winner)
  const loserPath = skillPath(skillsDir, loser)
  if (!existsSync(winnerPath) || !existsSync(loserPath)) {
    audit('supersede-refused', { detail: 'one of the two skills is not on disk' })
    return { applied: false, status: 'refused:missing-skill' }
  }
  const winnerSkill = readFileSync(winnerPath, 'utf8')
  const loserSkill = readFileSync(loserPath, 'utf8')
  const winnerValidity = readSkillValidity(winnerSkill)
  const loserValidity = readSkillValidity(loserSkill)

  // The guard: a machine-inferred rule may not retire a human-stated one.
  if (loserValidity.provenance === 'human' && winnerValidity.provenance !== 'human') {
    audit('supersede-refused', {
      detail: `refused: the loser is human-sourced and the winner is ${winnerValidity.provenance}`,
    })
    return { applied: false, status: 'refused:human-loser-protected' }
  }
  // An already-invalidated record is a timeline, not a conflict to re-open.
  if (loserValidity.invalidAt.length > 0) {
    return { applied: false, status: 'skipped:already-invalid' }
  }

  const reason = String(decision.reason ?? '').replace(/\s+/gu, ' ').trim().slice(0, 300)
  let loserText = loserSkill
  const invalidLine = `invalid_at: ${at}`
  loserText = /^invalid_at:/mu.test(loserText)
    ? loserText.replace(/^invalid_at:.*$/mu, invalidLine)
    : loserText.replace(/^(name:.*)$/mu, `$1\n${invalidLine}`)
  const supersededLine = `superseded_by: ${winner}`
  loserText = /^superseded_by:/mu.test(loserText)
    ? loserText.replace(/^superseded_by:.*$/mu, supersededLine)
    : loserText.replace(/^(name:.*)$/mu, `$1\n${supersededLine}`)
  if (!loserText.includes(`\`${winner}\``)) {
    const mention = `- 已被 \`${winner}\` 取代（${at.slice(0, 10)}${reason.length === 0 ? '' : `：${reason}`}）；不要再按本技能执行。`
    loserText = loserText.includes('## ⚠️ 已被取代')
      ? `${loserText.trimEnd()}\n${mention}\n`
      : `${loserText.trimEnd()}\n\n## ⚠️ 已被取代\n\n${mention}\n`
  }

  let winnerText = winnerSkill
  const existingSupersedes = winnerValidity.supersedes
  const merged = [...new Set([...existingSupersedes, loser])]
  const supersedesLine = `supersedes: ${merged.join(',')}`
  winnerText = /^supersedes:/mu.test(winnerText)
    ? winnerText.replace(/^supersedes:.*$/mu, supersedesLine)
    : winnerText.replace(/^(name:.*)$/mu, `$1\n${supersedesLine}`)
  if (!winnerText.includes(`\`${loser}\``)) {
    const mention = `- 取代了 \`${loser}\`（${at.slice(0, 10)}${reason.length === 0 ? '' : `：${reason}`}）。`
    winnerText = winnerText.includes('## 取代')
      ? `${winnerText.trimEnd()}\n${mention}\n`
      : `${winnerText.trimEnd()}\n\n## 取代\n\n${mention}\n`
  }

  atomicWrite(loserPath, loserText)
  atomicWrite(winnerPath, winnerText)
  audit('supersede')
  return { applied: true, status: 'superseded', invalidAt: at }
}

/**
 * READ ONE JSONL LEDGER.
 *
 * v1.1.0: this used to be `readFileSync` + line-by-line `JSON.parse` on EVERY call. The V8
 * profile put three instances of this function at 14.0% of a turn's CPU, and the retrieval
 * path re-parsed the same files again for another 13.2%. It now goes through the ledger
 * cache, which validates with two `stat` calls and returns the already-parsed array.
 *
 * The signature is unchanged on purpose: every caller keeps treating the result as a plain
 * array it may mutate, and `commitLedger` is what makes those mutations durable.
 */
function readJsonl(path        )                                 {
  return readRecords(path)
}

/**
 * Read a ledger that a caller is about to MUTATE under a lock.
 *
 * The cache returns a shared array; a caller that wants to be certain it is not holding a
 * snapshot taken before the lock must invalidate first. This is the explicit escape hatch —
 * named so that "did you mean the shared array or a fresh read?" has an answer at the call
 * site instead of in a comment.
 */
function readJsonlFresh(path        )                                 {
  invalidateLedger(path)
  return readRecords(path)
}

/**
 * v0.15 UI: the catalogue the console renders.
 *
 * One row per stored skill, carrying exactly what a human needs to judge it —
 * scene, scope, workspace, provenance, validity window, supersession — because a
 * list that shows only names forces the user back into the filesystem, which is
 * the problem the console exists to remove.
 */
                              
              
               
                     
              
               
               
                   
                              
                 
                   
                      
                      
                  
                                                                                               
                
                               
              
 

export function listSkillRecords(skillsDir        )                {
  const out                = []
  let names           = []
  try {
    names = readdirSync(skillsDir, { withFileTypes: true }).filter((entry) => entry.isDirectory()).map((entry) => entry.name)
  } catch {
    return out
  }
  for (const name of names) {
    const path = skillPath(skillsDir, name)
    let text = ''
    try {
      text = readFileSync(path, 'utf8')
    } catch {
      continue
    }
    const validity = readSkillValidity(text)
    const field = (key        )         => (text.match(new RegExp(`^${key}:\\s*(.+)$`, 'mu'))?.[1] ?? '').trim()
    const scene = field('scene').toLowerCase()
    out.push({
      name,
      title: (text.match(/^#\s+(.+)$/mu)?.[1] ?? name).trim(),
      description: field('description'),
      when: field('when_to_use') || field('when'),
      scope: field('scope') || 'project',
      scene: /^[a-z][a-z0-9-]{1,23}$/u.test(scene) ? scene : 'general',
      workspace: validity.validAt === '' && field('workspace') === '' ? '' : normalizeWorkspace(field('workspace')),
      provenance: validity.provenance,
      validAt: validity.validAt,
      invalidAt: validity.invalidAt,
      supersededBy: validity.supersededBy,
      supersedes: validity.supersedes,
      evidence: (field('evidence').split(',').filter((part) => part.trim().length > 0)).length,
      tags: asVocab(field('tags')),
      applicableNodeTypes: asVocab(field('applicable_node_types')),
      path,
    })
  }
  out.sort((left, right) => left.name.localeCompare(right.name))
  return out
}

                                   
                       
                  
                   
              
 

/**
 * v0.15 UI: "clear this workspace's memory" — as a MOVE, never a delete.
 *
 * A debugging convenience that erases data is a trap: the user clicks it once,
 * loses three weeks of learned rules, and never trusts the console again. So the
 * records are moved into a timestamped quarantine next to the store (same volume,
 * so the move is atomic) and the report names every file, which is also the
 * restore list.
 *
 * Matching is by the SAME rule retrieval uses (`memoryAllowsWorkspace`): records
 * from the given workspace, plus unscoped ones when `includeUnscoped` is set.
 * `global` records are never touched — they were deliberately made global.
 */
export function quarantineWorkspaceMemory(
  memoryDir        ,
  skillsDir        ,
  workspace        ,
  options                                                                   = {},
)                   {
  const stamp = (options.at ?? new Date().toISOString()).replace(/[:.]/gu, '-')
  const quarantineDir = join(memoryDir, `_quarantine-${stamp}`)
  const moved           = []
  let negatives = 0
  let kept = 0

  let names           = []
  try {
    names = readdirSync(skillsDir, { withFileTypes: true }).filter((entry) => entry.isDirectory()).map((entry) => entry.name)
  } catch {
    names = []
  }
  for (const name of names) {
    const path = skillPath(skillsDir, name)
    let text = ''
    try {
      text = readFileSync(path, 'utf8')
    } catch {
      continue
    }
    const validity = readSkillValidity(text)
    const scope = (text.match(/^scope:\s*(.+)$/mu)?.[1] ?? 'project').trim().toLowerCase()
    if (scope === 'global') {
      kept += 1
      continue
    }
    const recorded = readSkillWorkspace(text)
    const unscoped = recorded.length === 0
    const same = unscoped ? options.includeUnscoped === true : recorded === normalizeWorkspace(workspace)
    if (!same) {
      kept += 1
      continue
    }
    mkdirSync(join(quarantineDir, 'skills', name), { recursive: true })
    renameSync(path, join(quarantineDir, 'skills', name, 'SKILL.md'))
    rmSync(join(skillsDir, name), { recursive: true, force: true })
    moved.push(name)
    void validity
  }

  if (options.skillsOnly !== true) {
    /**
     * v0.31 P0 — THE QUARANTINE PATH WAS AN UNLOCKED READ-MODIFY-WRITE.
     *
     * This block reads ALL of `negatives.jsonl`, partitions it, and rewrites the
     * remainder. It took no lock, so a harvest appending a record at that moment had its
     * row silently erased by the rewrite — the same lost update the other five paths
     * were fixed for, in the one place nobody looked: a maintenance/diagnostic operation
     * that "cannot happen concurrently" in theory, and does in practice because a
     * harvest runs on its own timer.
     *
     * The lock is taken around the read AND the writes, and the read is INSIDE it — a
     * value read before taking the lock is stale by definition.
     */
    const path = join(memoryDir, 'negatives.jsonl')
    if (existsSync(path)) {
      const release = acquireFileLock(`${path}.lock`, { label: 'quarantineNegatives' })
      try {
        const records = readJsonl(path)
        const keep                                 = []
        const drop                                 = []
        for (const record of records) {
          const scope = String(record.scope ?? 'project').toLowerCase()
          if (scope === 'global') {
            keep.push(record)
            continue
          }
          const recorded = normalizeWorkspace(record.workspace)
          const unscoped = recorded.length === 0
          const same = unscoped ? options.includeUnscoped === true : recorded === normalizeWorkspace(workspace)
          if (same) drop.push(record)
          else keep.push(record)
        }
        if (drop.length > 0) {
          mkdirSync(quarantineDir, { recursive: true })
          atomicWrite(join(quarantineDir, 'negatives.jsonl'), drop.map((record) => JSON.stringify(record)).join('\n') + '\n')
          atomicWrite(path, keep.map((record) => JSON.stringify(record)).join('\n') + (keep.length > 0 ? '\n' : ''))
          negatives = drop.length
        }
      } finally {
        release()
      }
    }
  }

  if (moved.length > 0 || negatives > 0) {
    mkdirSync(quarantineDir, { recursive: true })
    atomicWrite(
      join(quarantineDir, 'MANIFEST.json'),
      JSON.stringify({ at: new Date().toISOString(), workspace: normalizeWorkspace(workspace), skills: moved, negatives, kept }, null, 2) + '\n',
    )
  }
  return { quarantineDir, skills: moved, negatives, kept }
}

/**
 * v0.25 P1 — LOCKED READ-MODIFY-WRITE FOR A JSONL STORE FILE.
 *
 * The lost update is not specific to `processed.json`. Every jsonl layer file
 * (negatives, facts, experiences) is edited by READ-ALL, mutate-in-memory,
 * WRITE-ALL, and `atomicWrite` does nothing about that: it guarantees the file
 * changes all at once, not that the change was computed from the current contents.
 *
 * The interleaving that loses data:
 *
 *     A reads 10 rows ─┐
 *     B reads 10 rows ─┼─ both append their own row
 *     A writes 11 ─────┘
 *     B writes 11      ← A's row is gone, silently
 *
 * Two harvests of two different sessions is the normal case, not a rare one: the
 * harvest loop processes several sessions, and two Harvests can run in parallel from
 * two windows. So the whole read→mutate→write is done under one lock.
 *
 * The lock is a SIBLING directory (`<path>.lock`), the same primitive `markProcessed`
 * already uses, so there is one locking discipline in this store rather than two.
 *
 * The body returns whether anything changed; an unchanged pass does not rewrite, so
 * a read-only sweep does not fight other writers for the lock's sake.
 */
function updateJsonlFile   (path        , body                                                                      )    {
  mkdirSync(dirname(path), { recursive: true })
  return withFileLock(`${path}.lock`, () => {
    const rows = readJsonl(path)
    const { changed, result } = body(rows                             )
    if (changed) atomicWrite(path, rows.map((record) => JSON.stringify(record)).join('\n') + (rows.length > 0 ? '\n' : ''))
    return result
  })
}

/**
 * v1.0.0 P0 — THE NEGATIVE LEDGER HAD NO CEILING.
 *
 * `negatives.jsonl` only ever grew. Every harvest may append; dedupe merges EXACT
 * duplicates but nothing bounds the number of distinct ones. Left alone that is an
 * unbounded file that every `appendNegatives` (read-all, mutate, rewrite) and every
 * retrieval (read-all, tokenize) has to carry — so the cost of an old warning is paid on
 * every future turn, forever.
 *
 * THE POLICY, AND WHY IT IS NOT "DROP THE OLDEST"
 *
 * A negative path is a rule of the form "doing A fails". Age alone is not a reason to
 * retire it: an old rule that keeps being HIT is a real, recurring hazard, and dropping it
 * would relearn the same failure. So the ordering is:
 *
 *   1. `hits` DESC  — re-confirmed rules survive longest
 *   2. `confidence` DESC — rules not undermined by counter-evidence survive
 *   3. `at` DESC    — then newest first
 *
 * Whatever falls past `MAX_NEGATIVES` is APPENDED to `negatives-archive.jsonl` and removed
 * from the live file. Nothing is destroyed: the archive stays greppable and auditable, it
 * simply stops participating in retrieval — the same "cost, not loss" contract that
 * archiving a skill already uses.
 *
 * The thresholds are exported so a test can assert the boundary instead of inferring it.
 */
export const MAX_NEGATIVES = 5000
export const NEGATIVE_ARCHIVE_FILE = 'negatives-archive.jsonl'

                                      
                                      
                                         
 

/** Split records into the live set and the overflow, keeping the most load-bearing first. */
export function planNegativeArchive(records                                        , limit = MAX_NEGATIVES)                      {
  if (records.length <= limit) return { keep: [...records], archive: [] }
  const rank = (record                         )           => {
    const hits = Number(record.hits ?? 1)
    const confidence = Number(record.confidence ?? 1)
    const at = Date.parse(String(record.at ?? ''))
    return [
      Number.isFinite(hits) ? hits : 1,
      Number.isFinite(confidence) ? confidence : 1,
      Number.isFinite(at) ? at : 0,
    ]
  }
  const sorted = [...records].sort((left, right) => {
    const a = rank(left)
    const b = rank(right)
    for (let index = 0; index < a.length; index += 1) {
      if (a[index] !== b[index]) return b[index] - a[index]
    }
    return String(left.symptom ?? '').localeCompare(String(right.symptom ?? ''))
  })
  return { keep: sorted.slice(0, limit), archive: sorted.slice(limit) }
}

export function appendNegatives(memoryDir        , negatives                     , meta           )         {
  if (negatives.length === 0) return 0
  const workspace = normalizeWorkspace(meta.workspace)
  const path = join(memoryDir, 'negatives.jsonl')
  let appended = 0
  let dirty = false
  /**
   * v1.1.0: no pre-lock read. It only warmed a local array; the authoritative read now
   * happens inside the lock via the stat-validated cache, so a pre-lock parse would be a
   * wasted full file read.
   */
  const release = acquireFileLock(`${path}.lock`, { label: 'appendNegatives' })
  try {
    const existing = readJsonl(path)
    const beforeLength = existing.length
    let patched = false
    appended = 0
    dirty = false
    for (const negative of negatives) {
      if (scanThreat(`${negative.symptom} ${negative.cause} ${negative.avoid}`) !== undefined) continue
      // Gates ② (exact) and ④ (same symptom, different cause → link, never merge).
      const plan = planNegative(existing         , negative)
      if (plan.duplicate) {
        /**
         * ── THE `plan.conflicts.length === 0` GUARD WAS A BUG ─────────────────────────────────
         *
         * The duplicate row was located with:
         *
         *     existing.find((record) => plan.conflicts.length === 0 && record.symptom === … && record.cause === …)
         *
         * `plan.conflicts` describes the WHOLE existing set, not this one candidate: it lists every
         * row that shares the symptom and differs in cause. So as soon as the store held BOTH a
         * duplicate AND a conflicting variant, `plan.conflicts.length` was non-zero and the find
         * returned `undefined` — neither merged nor linked. Measured: three repeats of the same
         * symptom+cause produced one row with `hits: 3` (correct, by luck of ordering), but a store
         * holding a variant first kept re-appending instead of merging, and `conflictsWith` was
         * never written on the duplicate path at all.
         *
         * The identity of a duplicate is `symptom + cause` and nothing else. The conflict list is
         * a SEPARATE concern that is attached when the row is created.
         */
        const same = existing.find(
          (record) => String(record.symptom) === negative.symptom && String(record.cause) === negative.cause,
        )
        if (same !== undefined) {
          const keyOf = (ref     )         => (ref !== null && typeof ref === 'object' ? `${ref.sourceSessionId}@${ref.seq}` : String(ref))
          const merged = [...new Map([...(Array.isArray(same.evidence) ? same.evidence : []), ...negative.evidence].map((ref) => [keyOf(ref), ref])).values()]
          same.evidence = merged
          same.hits = Number(same.hits ?? 0) + 1
          /**
           * A repeat can ALSO reveal a conflict: the row was already there, and the store has since
           * accumulated variants. Recording the indexes here is what makes the causal layer usable
           * for rows that predate their conflicts — otherwise `conflictsWith` would only ever exist
           * on the first incarnation of a symptom.
           */
          if (plan.conflicts.length > 0) {
            const prior = Array.isArray(same.conflictsWith) ? same.conflictsWith : []
            const union = [...new Set([...prior, ...plan.conflicts])].sort((left, right) => left - right)
            same.conflictsWith = union
          }
          patched = true
          dirty = true
        }
        continue
      }
      existing.push({
        ...negative,
        scope: negative.scope ?? 'project',
        domain: negative.domain ?? 'general',
        // v0.5: confidence starts at 1 and is lowered by counter-evidence, never
        // raised by repetition alone (a repeated failure is not a stronger rule).
        confidence: 1,
        counterEvidence: [],
        sourceSessionId: meta.sessionId,
        boundarySeq: meta.boundarySeq,
        // v0.32: the physical trace, on negatives too — a blocker with no time cannot be ordered in the chain.
        timestamp: monotonicTimestamp(),
        at: meta.at ?? new Date().toISOString(),
        hits: 1,
        // v0.8: same isolation contract as SKILL.md.
        ...(workspace.length === 0 ? {} : { workspace }),
        // v0.15: the same bi-temporal + trust contract as SKILL.md, so a negative
        // can be superseded (and stop being retrieved) without being deleted.
        provenance: negative.provenance ?? meta.provenance ?? 'inferred',
        valid_at: meta.validAt ?? meta.at ?? new Date().toISOString(),
        ...(() => {
          const tags = asVocab((negative                     ).tags)
          return tags.length === 0 ? {} : { tags }
        })(),
        ...(() => {
          const nodeTypes = asVocab((negative                     ).applicableNodeTypes)
          return nodeTypes.length === 0 ? {} : { applicable_node_types: nodeTypes }
        })(),
        ...(plan.conflicts.length === 0 ? {} : { conflictsWith: plan.conflicts }),
      })
      appended += 1
      dirty = true
    }
    if (!dirty) return 0
    /**
     * v1.0.0 P0: enforce the ceiling INSIDE the same lock as the append. Trimming outside
     * it would race a concurrent harvest that is rewriting the same file.
     */
    if (existing.length > MAX_NEGATIVES) {
      const overflow = planNegativeArchive(existing, MAX_NEGATIVES)
      if (overflow.archive.length > 0) {
        appendFileSync(join(memoryDir, NEGATIVE_ARCHIVE_FILE), `${overflow.archive.map((record) => JSON.stringify(record)).join('\n')}\n`, 'utf8')
        replaceRecords(path, overflow.keep)
        return appended
      }
    }
    /**
     * v1.1.0 — THE HOT PATH IS NO LONGER A FULL REWRITE.
     *
     * New rows go to the WAL (one append); a `hits += 1` patch forces an immediate flush
     * because a patch cannot be expressed as an append. The common case is append-only,
     * so the common case is O(1).
     */
    commitLedger(path, existing.slice(beforeLength), { patched })
    return appended
  } finally {
    release()
  }
}

                       
              
                
                                                                  
                 
                                                                             
                    
                                                                             
                                       
                         
                     
            
              
 

/** Accept both pointer shapes and attach the fallback session to a bare seq. */
function normalizeEvidenceRefs(value         , fallbackSession        )                {
  const out                = []
  const raw = Array.isArray(value) ? value : []
  for (const item of raw) {
    let seq        
    let session        
    if (item !== null && typeof item === 'object') {
      seq = Number((item       ).seq)
      const id = typeof (item       ).sourceSessionId === 'string' ? String((item       ).sourceSessionId) : ''
      session = id.length > 0 ? id : fallbackSession
    } else {
      seq = Number(item)
      session = fallbackSession
    }
    if (!Number.isFinite(seq)) continue
    if (out.some((ref) => ref.seq === seq && ref.sourceSessionId === session)) continue
    out.push({ sourceSessionId: session, seq })
  }
  return out
}

/**
 * v0.5: counter-evidence — the ONLY mechanism that can weaken a stored rule.
 *
 * A negative path says "doing A fails". When a later session does A and it
 * SUCCEEDS, the rule has been falsified in practice. Silently keeping it at full
 * weight is how a stale rule becomes a permanent prohibition; deleting it on one
 * success is the opposite mistake (the old failure may still happen elsewhere).
 * So: record the seq as `counterEvidence`, lower `confidence` by a step, and let
 * retrieval rank it down. The rule survives, visibly weakened, with its receipt.
 */
                                        
                                                                      
                        
 

export function recordCounterEvidence(
  memoryDir        ,
  events                                                        ,
)                        {
  const path = join(memoryDir, 'negatives.jsonl')
  const records = readJsonl(path)
  if (records.length === 0) return { updated: [], scannedResults: 0 }

  const callNames = new Map                ()
  const successes                                                     = []
  for (const event of events) {
    if (event?.type === 'tool/call') {
      const callId = typeof event.data?.callId === 'string' ? event.data.callId : ''
      const name = typeof event.data?.name === 'string' ? event.data.name : ''
      if (callId.length > 0 && name.length > 0) callNames.set(callId, name)
      continue
    }
    if (event?.type !== 'tool/result') continue
    const message = event.data?.message
    if (message?.isError === true || event.data?.error !== undefined) continue
    const callId = message?.source?.callId ?? message?.toolCallId
    const tool = typeof callId === 'string' ? (callNames.get(String(callId)) ?? '') : ''
    if (tool.length === 0) continue
    const content = Array.isArray(message?.content) ? message.content : []
    const text = content
      .filter((block     ) => block?.type === 'text' && typeof block.text === 'string')
      .map((block     ) => block.text)
      .join(' ')
    successes.push({ seq: Number(event.seq ?? 0), tool, text: text.slice(0, 2000) })
  }

  const updated                                   = []
  let dirty = false
  // v0.25 P1: read and write in ONE critical section. This function rewrites the whole
  // negatives file; without the lock, a concurrent `appendNegatives` or a second
  // counter sweep would be erased by whichever wrote last.
  const release = acquireFileLock(`${path}.lock`, { label: 'recordCounterEvidence' })
  try {
    /**
     * v1.1.0 — NO CLEAR-AND-REFILL.
     *
     * This used to be `records.length = 0; records.push(...readJsonl(path))`, a re-read
     * inside the lock to defeat a stale pre-lock snapshot. With the ledger cache that is
     * catastrophic: `readJsonl` returns the SAME array instance, so clearing it and then
     * spreading it yields an empty array — every negative silently deleted. The cache is
     * already stat-validated under the lock, so the re-read is unnecessary; `invalidate`
     * first to be certain we are not looking at a snapshot another process invalidated.
     */
    const live = readJsonlFresh(path)
    updated.length = 0
    dirty = false
    for (const record of live) {
      const symptom = String(record.symptom ?? '')
      const cause = String(record.cause ?? '')
      const avoid = String(record.avoid ?? '')
      const haystack = `${symptom} ${cause} ${avoid}`
      const tokens = new Set(
        (haystack.toLowerCase().match(/[a-z][a-z0-9_-]{2,}/gu) ?? []).filter(
          (token) => !['the', 'and', 'with', 'for', 'this', 'that', 'from', 'then', 'than', 'into'].includes(token),
        ),
      )
      if (tokens.size === 0) continue
      const seen = new Set((Array.isArray(record.counterEvidence) ? record.counterEvidence : []).map(Number))
      for (const success of successes) {
        if (seen.has(success.seq)) continue
        if (!tokens.has(success.tool.toLowerCase())) continue
        // The success must not still show the symptom it is supposed to refute.
        const symptomWords = (symptom.match(/[\u4e00-\u9fff]{2,}/gu) ?? []).slice(0, 3)
        if (symptomWords.some((word) => success.text.includes(word))) continue
        const counter = [...seen, success.seq]
        seen.add(success.seq)
        record.counterEvidence = counter
        const confidence = Number(record.confidence ?? 1)
        record.confidence = Math.max(0.2, Math.round((confidence - 0.2) * 100) / 100)
        record.lastCounterAt = new Date().toISOString()
        updated.push({ symptom: symptom.slice(0, 80), seq: success.seq, confidence: Number(record.confidence) })
        dirty = true
      }
    }
    if (dirty) commitLedger(path, [], { patched: true })
    return { updated, scannedResults: successes.length }
  } finally {
    release()
  }
}

/** v0.7: record that a recalled skill was actually used (drives decay). */
export function touchSkillUsage(skillsDir        , name        , at         )          {
  const path = skillPath(skillsDir, name)
  if (!existsSync(path)) return false
  try {
    let text = readFileSync(path, 'utf8')
    const stamp = at ?? new Date().toISOString()
    text = /^last_used:/mu.test(text)
      ? text.replace(/^last_used:.*$/mu, `last_used: ${stamp}`)
      : text.replace(/^(name:.*)$/mu, `$1\nlast_used: ${stamp}`)
    atomicWrite(path, text)
    /** v1.1.0: a usage stamp changes last_used/decay, which retrieval derives from. */
    invalidateSkillDocs(skillsDir)
    return true
  } catch {
    return false
  }
}

                                                   

                                 
                                                                              
                   
 

/**
 * v0.7.1: the use-effect loop.
 *
 * Extraction can only prove that a procedure was written down; it cannot prove
 * the procedure still works. turn-stopping knows the outcome of the turn that
 * actually used the skill: a clean turn (no failed tool result) confirms it, a
 * turn that retried after an error weakens it. This is the ONLY automatic
 * mechanism that can raise confidence — and it raises it by a small step, so a
 * lucky turn cannot launder a bad skill.
 */
export function applySkillFeedback(
  skillsDir        ,
  names                   ,
  outcome               ,
  at         ,
)                 {
  const stamp = at ?? new Date().toISOString()
  const updated                            = []
  const missing           = []
  const seen = new Set        ()
  for (const raw of names) {
    const name = String(raw ?? '').trim()
    if (name.length === 0 || seen.has(name)) continue
    seen.add(name)
    const path = skillPath(skillsDir, name)
    if (!existsSync(path)) {
      missing.push(name)
      continue
    }
    try {
      let text = readFileSync(path, 'utf8')
      const previous = clampConfidence(text.match(/^confidence:\s*(.+)$/mu)?.[1])
      const next = outcome === 'positive' ? Math.min(1, Math.round((previous + 0.05) * 100) / 100) : Math.max(0.2, Math.round((previous - 0.1) * 100) / 100)
      text = /^confidence:/mu.test(text)
        ? text.replace(/^confidence:.*$/mu, `confidence: ${next.toFixed(2)}`)
        : text.replace(/^(name:.*)$/mu, `$1\nconfidence: ${next.toFixed(2)}`)
      text = /^last_feedback:/mu.test(text)
        ? text.replace(/^last_feedback:.*$/mu, `last_feedback: ${outcome}`)
        : text.replace(/^(name:.*)$/mu, `$1\nlast_feedback: ${outcome}`)
      if (outcome === 'positive') {
        // Confirmed in use = validated now; this restarts the decay clock.
        text = /^last_validated:/mu.test(text)
          ? text.replace(/^last_validated:.*$/mu, `last_validated: ${stamp}`)
          : text.replace(/^(name:.*)$/mu, `$1\nlast_validated: ${stamp}`)
      }
      atomicWrite(path, text)
      updated.push({ name, outcome, confidence: next })
    } catch {
      missing.push(name)
    }
  }
  /** v1.1.0: confidence feeds scoring, so the cached documents are now stale. */
  if (updated.length > 0) invalidateSkillDocs(skillsDir)
  return { updated, missing }
}

                                          
                   
                                                                
                                                    
                   
               
                     
                                                                           
                 
 

/**
 * v0.7.1: ONE-SHOT legacy repair for the v0.5/v0.6 bare-seq era.
 *
 * Before the composite key, `evidence: 14926` was stored without a session id.
 * After a generation hop that seq is meaningless: `graft_read_result` needs the
 * session. The migration attaches the given session id to every bare pointer. It
 * is explicit (a tool the user calls), never a silent rewrite on activation: a
 * wrong attribution is worse than a visible missing one.
 */
export function migrateBareEvidence(memoryDir        , skillsDir        , sessionId        )                          {
  const session = String(sessionId ?? '').trim()
  if (session.length === 0) throw new Error('migrateBareEvidence: a sourceSessionId is required')
  const result                          = { sessionId: session, skills: [], negatives: 0, facts: 0, experiences: 0, already: 0 }

  for (const name of listSkillFiles(skillsDir)) {
    const path = skillPath(skillsDir, name)
    if (!existsSync(path)) continue
    try {
      let text = readFileSync(path, 'utf8')
      const line = text.match(/^evidence:\s*(.+)$/mu)
      if (line === null) continue
      const tokens = line[1].split(/[,\s]+/u).filter(Boolean)
      let rewritten = 0
      let composite = 0
      const next = tokens.map((token) => {
        if (token.includes('@')) {
          composite += 1
          return token
        }
        rewritten += 1
        return `${session}@${token}`
      })
      result.already += composite
      if (rewritten === 0) continue
      text = text.replace(/^evidence:.*$/mu, `evidence: ${next.join(',')}`)
      atomicWrite(path, text)
      result.skills.push({ name, rewritten })
    } catch {
      // A file that cannot be parsed keeps its pointers; it is reported elsewhere.
    }
  }

  const migrateJsonl = (file        , key                                       )       => {
    const path = join(memoryDir, file)
    if (!existsSync(path)) return
    // v0.25 P1: this is a whole-file rewrite (attach a sessionId to every bare seq), so
    // it takes the same lock as the writers it would otherwise clobber. The read must be
    // INSIDE the lock, or a concurrent append is silently dropped.
    const release = acquireFileLock(`${path}.lock`, { label: `migrateEvidence:${file}` })
    try {
      const records = readJsonl(path)
      let changed = 0
      for (const record of records) {
        const evidence = Array.isArray(record.evidence) ? record.evidence : []
        let dirty = false
        const merged            = []
        for (const item of evidence) {
          if (item !== null && typeof item === 'object' && Number.isFinite(Number((item       ).seq))) {
            if (typeof (item       ).sourceSessionId !== 'string' || String((item       ).sourceSessionId).length === 0) {
              merged.push({ sourceSessionId: session, seq: Number((item       ).seq) })
              dirty = true
            } else {
              merged.push(item)
            }
            result.already += 1
            continue
          }
          const seq = Number(item)
          if (Number.isFinite(seq)) {
            merged.push({ sourceSessionId: session, seq })
            dirty = true
            continue
          }
          merged.push(item)
        }
        if (!dirty) continue
        record.evidence = merged
        if (typeof record.sourceSessionId !== 'string' || String(record.sourceSessionId).length === 0) record.sourceSessionId = session
        changed += 1
      }
      if (changed > 0) atomicWrite(path, records.map((record) => JSON.stringify(record)).join('\n') + '\n')
      result[key] = changed
    } finally {
      release()
    }
  }
  migrateJsonl('negatives.jsonl', 'negatives')
  migrateJsonl('facts.jsonl', 'facts')
  migrateJsonl('experiences.jsonl', 'experiences')
  return result
}

/** v0.7: new evidence re-validates a skill (cancels decay for 14 days). */
export function markSkillValidated(skillsDir        , name        , at         )          {
  const path = skillPath(skillsDir, name)
  if (!existsSync(path)) return false
  try {
    let text = readFileSync(path, 'utf8')
    const stamp = at ?? new Date().toISOString()
    text = /^last_validated:/mu.test(text)
      ? text.replace(/^last_validated:.*$/mu, `last_validated: ${stamp}`)
      : text.replace(/^(name:.*)$/mu, `$1\nlast_validated: ${stamp}`)
    atomicWrite(path, text)
    /** v1.1.0: re-validation clears the stale flag, which the cached document still carries. */
    invalidateSkillDocs(skillsDir)
    return true
  } catch {
    return false
  }
}

/** Append facts/experiences, merging evidence (never instructions, only pointers). */

function appendLayer(
  memoryDir        ,
  file        ,
  entries                 
                
               
                  
                   
                      
                   
                    
                   
    ,
  meta           ,
)         {
  if (entries.length === 0) return 0
  const workspace = normalizeWorkspace(meta.workspace)
  const path = join(memoryDir, file)
  let appended = 0
  let dirty = false
  /** v1.1.0: no pre-lock read; the authoritative read is inside the lock via the cache. */
  const release = acquireFileLock(`${path}.lock`, { label: `appendLayer:${file}` })
  try {
    const existing = readJsonl(path)                            
    const beforeLength = existing.length
    let patched = false
    appended = 0
    dirty = false
    for (const entry of entries) {
    if (scanThreat(entry.text) !== undefined) continue
    const same = existing.find((record) => record.text === entry.text)
    if (same !== undefined) {
      // v0.7.1: evidence is composite everywhere, not just in SKILL.md.
      const refs = normalizeEvidenceRefs(same.evidence, meta.sessionId)
      if (!refs.some((ref) => ref.seq === entry.seq && ref.sourceSessionId === meta.sessionId)) {
        refs.push({ sourceSessionId: meta.sessionId, seq: entry.seq })
      }
      same.evidence = refs
      same.hits = Number(same.hits ?? 0) + 1
      patched = true
      dirty = true
      continue
    }
    existing.push({
      text: entry.text,
      scene: /^[a-z][a-z0-9-]{1,23}$/u.test(String(entry.scene ?? '')) ? String(entry.scene) : 'general',
      /**
       * NOTE the single `domain` key. The previous revision declared it TWICE in this object literal — the
       * second silently won, which happened to be identical, so nothing ever failed. That is the kind of
       * duplication that becomes a real bug the moment one copy is edited.
       */
      domain: /^[a-z][a-z0-9-]{1,31}$/u.test(String(entry.domain ?? '').toLowerCase())
        ? String(entry.domain).toLowerCase()
        : 'general',
      /**
       * v0.32: the physical trace. An explicit `entry.timestamp` is honoured (a caller replaying an ordered
       * batch keeps its own order); otherwise the monotonic clock stamps it.
       */
      timestamp: typeof entry.timestamp === 'string' && entry.timestamp.length > 0
        ? entry.timestamp
        : monotonicTimestamp(),
      /**
       * v1.7.0 — ENTITY CANONICALISATION AT WRITE TIME.
       *
       * The causal walk joins nodes by `cause`/`effect` STRINGS. A memory that says `prod-db` and
       * another that says `生产数据库` are therefore two unrelated nodes, and the chain that runs
       * through both stops at the boundary — which looks like a shallow graph when the graph is
       * fine and the NAMES are not.
       *
       * Canonicalising on READ would be wrong twice over: every walk would pay the rewrite, and two
       * records could disagree about what they call the same machine. Normalising on WRITE means
       * the stored edge text is already the canonical name, so the graph is connected by
       * construction. The original wording survives in `text`/`avoid`, so nothing is lost for a
       * human reader.
       *
       * ⚠️ ONLY STRINGS ARE CANONICALISED. `cause` and `effect` may also be POINTER OBJECTS
       * (`{sourceSessionId, seq}`), and an earlier version ran `String(...)` over them
       * unconditionally — which turned a pointer into the literal text `[object Object]` and broke
       * every causal chain built from an experience. The test that caught it asserted
       * `extra.cause === 'session-causal@20'` and got `undefined`.
       */
      ...(typeof entry.cause === 'string'
        ? { cause: canonicalizeEntities(entry.cause) }
        : entry.cause === undefined
          ? {}
          : { cause: entry.cause }),
      ...(typeof entry.effect === 'string'
        ? { effect: canonicalizeEntities(entry.effect) }
        : entry.effect === undefined
          ? {}
          : { effect: entry.effect }),
      ...(typeof entry.action === 'string' && entry.action.length > 0 ? { action: entry.action } : {}),
      evidence: [{ sourceSessionId: meta.sessionId, seq: entry.seq }],
      sourceSessionId: meta.sessionId,
      boundarySeq: meta.boundarySeq,
      at: meta.at ?? new Date().toISOString(),
      hits: 1,
      ...(workspace.length === 0 ? {} : { workspace }),
    })
    appended += 1
    dirty = true
  }
    if (!dirty) return 0
    /**
     * v1.1.1 — FACTS AND EXPERIENCES GET A CEILING TOO.
     *
     * Measured in a 10-minute multi-agent stress run: negatives stabilised at their 5000 cap
     * after 120 s, while `facts` and `experiences` kept climbing past 6000 — and the heap
     * climbed with them (21 MB → 181 MB, RSS 78 MB → 405 MB), while throughput fell from 62 to
     * 30 turns/s. The documents derived from those rows carry a token set each, so an
     * unbounded layer is not "just more JSONL": it is memory that never comes back.
     *
     * Same contract as the negative ledger: the overflow is APPENDED to a sibling archive and
     * dropped from the live file. Nothing is destroyed; the archive is still greppable, it
     * simply stops being loaded on every retrieval.
     */
    if (existing.length > MAX_LAYER_RECORDS) {
      const overflow = planLayerArchive(existing                                             , MAX_LAYER_RECORDS)
      if (overflow.archive.length > 0) {
        appendFileSync(join(memoryDir, `${file}.archive`), `${overflow.archive.map((record) => JSON.stringify(record)).join('\n')}\n`, 'utf8')
        replaceRecords(path, overflow.keep)
        return appended
      }
    }
    /** v1.1.0: append-only rows go to the WAL; a `hits += 1` patch forces a flush. */
    commitLedger(path, existing.slice(beforeLength), { patched })
    return appended
  } finally {
    release()
  }
}

/**
 * How many facts / experiences stay live before the oldest are archived.
 *
 * Larger than `MAX_NEGATIVES` because these are observational layers with a higher natural
 * volume (one fact and one experience per turn, versus a handful of negatives per session),
 * and because retrieval treats them as supporting evidence rather than as rules.
 */
export const MAX_LAYER_RECORDS = 10_000

/**
 * Split a layer into the live set and the overflow.
 *
 * Ordering is NEWEST FIRST for these layers: a fact or an experience describes what happened,
 * and an observation from three months ago is worth less than one from yesterday. `hits`
 * breaks ties — something re-confirmed is more load-bearing than something seen once — and
 * `timestamp` (the monotonic write clock) is the final tiebreak so the split is deterministic.
 */
function planLayerArchive(
  records                                        ,
  limit = MAX_LAYER_RECORDS,
)                                                                                    {
  if (records.length <= limit) return { keep: [...records], archive: [] }
  const rank = (record                         )           => {
    const hits = Number(record.hits ?? 1)
    const at = Date.parse(String(record.timestamp ?? record.at ?? ''))
    return [Number.isFinite(hits) ? hits : 1, Number.isFinite(at) ? at : 0]
  }
  const sorted = [...records].sort((left, right) => {
    const a = rank(left)
    const b = rank(right)
    for (let index = 0; index < a.length; index += 1) {
      if (a[index] !== b[index]) return b[index] - a[index]
    }
    return String(left.text ?? '').localeCompare(String(right.text ?? ''))
  })
  return { keep: sorted.slice(0, limit), archive: sorted.slice(limit) }
}

export function appendFacts(memoryDir        , facts                          , meta           )         {
  return appendLayer(memoryDir, 'facts.jsonl', facts, meta)
}

export function appendExperiences(memoryDir        , experiences                                , meta           )         {
  return appendLayer(memoryDir, 'experiences.jsonl', experiences, meta)
}

export function processedKey(sessionId        , boundarySeq        )         {
  return `${sessionId}:${boundarySeq}`
}

/**
 * v0.22 P0: read-modify-write a JSON array under a FILE LOCK.
 *
 * `atomicWrite` closes the torn-read window; it does not close the lost-update
 * window. Two harvests that both read `processed.json`, add their own key and write
 * back will keep only the second key — the first session looks unprocessed and gets
 * mined again. The lock is what makes the RMW a single step.
 */
function updateJsonArrayFile(path        , mutate                             )       {
  mkdirSync(dirname(path), { recursive: true })
  withFileLock(`${path}.lock`, () => {
    const keys = (() => {
      try {
        const parsed = JSON.parse(readFileSync(path, 'utf8'))
        if (!Array.isArray(parsed)) return new Set        ()
        return new Set(parsed.filter((value)                  => typeof value === 'string'))
      } catch {
        return new Set        ()
      }
    })()
    mutate(keys)
    atomicWrite(path, JSON.stringify([...keys], null, 2) + '\n')
  })
}

export function readProcessed(memoryDir        )              {
  const path = join(memoryDir, 'processed.json')
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8'))
    if (!Array.isArray(parsed)) return new Set()
    return new Set(parsed.filter((value)                  => typeof value === 'string'))
  } catch {
    return new Set()
  }
}

/**
 * Record that a session boundary was mined.
 *
 * v0.22 P0: locked RMW. The previous version read, mutated in memory and replaced the
 * whole file, so a concurrent harvest's key vanished. `processed.json` is the ONLY
 * guard against mining the same boundary twice, which makes a lost key a duplicate
 * skill, not a cosmetic counter.
 *
 * Pass `{ expected: false }` to make this a no-op when the boundary is already
 * recorded — that is what a retry-after-failure needs, and it must not resurrect a
 * cursor another writer already advanced.
 */
export function markProcessed(memoryDir        , key        )       {
  updateJsonArrayFile(join(memoryDir, 'processed.json'), (keys) => {
    keys.add(key)
  })
}

/** v0.22: is this boundary already recorded? A READ, safe without the lock. */
export function isProcessed(memoryDir        , key        )          {
  return readProcessed(memoryDir).has(key)
}

                              
                
                   
               
                     
                   
                   
                   
 

function countJsonl(path        )         {
  try {
    return readFileSync(path, 'utf8').split(/\r?\n/u).filter(Boolean).length
  } catch {
    return 0
  }
}

export function stats(memoryDir        , skillsDir        )              {
  const skills = (() => {
    try {
      return readdirNames(skillsDir).length
    } catch {
      return 0
    }
  })()
  return {
    skills,
    negatives: countJsonl(join(memoryDir, 'negatives.jsonl')),
    facts: countJsonl(join(memoryDir, 'facts.jsonl')),
    experiences: countJsonl(join(memoryDir, 'experiences.jsonl')),
    processed: readProcessed(memoryDir).size,
    memoryDir,
    skillsDir,
  }
}

function readdirNames(dir        )           {
  return readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
}

/**
 * v0.22 P1 — PROGRESSIVE DISCLOSURE: the body is a SECOND read, not part of the hint.
 *
 * THE BUDGET PROBLEM
 *
 * A SKILL.md is a procedure: frontmatter, 执行步骤, 验证标准, pitfalls. The hint that
 * rides a pre-step is a single line, and it deliberately carries only the trigger —
 * `when_to_use` — because that is what decides "is this skill about my task".
 *
 * Injecting the body as well would spend the context budget of EVERY turn on every
 * recalled skill, whether or not the model acts on it: measured on this store, the
 * four largest skills are ~2.4 KB each, so three recalls per turn would cost ~7 KB of
 * a 32k window — paid before anyone decides the skill applies.
 *
 * So the body is read ON DEMAND: the hint names the skill, and `skill_read(name)`
 * returns the procedure when the model has decided it wants it.
 *
 * Read-only, and it applies the same injection scan as retrieval: a body that was
 * poisoned on disk must not reach a prompt through this path either.
 */
                            
              
               
              
                                                 
              
                                                                          
               
     
                                                                
    
                                                                                                        
                                                                                                           
                                                                                            
    
                                                                                                            
                                                                
     
                                                                
                                                                                                 
                       
 

/**
 * Parse a frontmatter list of evidence pointers.
 *
 * WHY A TOLERANT PARSER: frontmatter is hand-edited (that is a feature — a human can correct a skill), so a
 * malformed entry must be SKIPPED rather than made to throw. A skill whose dependency line is typo'd should
 * still be readable; only that one precondition is lost, and the loss is silent by construction because the
 * alternative is making a whole skill unreadable over one bad line.
 */
function parseEvidenceList(raw        , field        )                                                  {
  const items = raw
    .split(/[,\s]+/u)
    .map((item) => item.trim())
    .filter((item) => item.length > 0)
  const out                                                  = []
  for (const item of items) {
    // Accept `sessionId@seq` and bare `seq`.
    const at = item.lastIndexOf('@')
    if (at > 0) {
      const seq = Number(item.slice(at + 1))
      if (Number.isFinite(seq)) out.push({ sourceSessionId: item.slice(0, at), seq })
      continue
    }
    const seq = Number(item)
    if (Number.isFinite(seq)) out.push({ sourceSessionId: '', seq })
  }
  if (out.length === 0 && raw.trim().length > 0) {
    void field
  }
  return out
}

export function readSkillBody(skillsDir        , name        )                        {
  // The name is a directory under skillsDir; refuse anything that could escape it.
  if (typeof name !== 'string' || name.length === 0) return undefined
  if (name.includes('/') || name.includes('\\') || name.includes('..')) return undefined
  const path = skillPath(skillsDir, name)
  let text = ''
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    return undefined
  }
  // The same rule the write gate and the retrieval gate apply: stored memory is DATA,
  // and text that tries to rewrite the reader's rules is refused at THIS boundary too.
  if (scanThreat(text) !== undefined) return undefined
  const field = (key        )         => (text.match(new RegExp(`^${key}:\\s*(.+)$`, 'mu'))?.[1] ?? '').trim()
  const body = text.replace(/^---[\s\S]*?---\u0000?/u, '').replace(/^---[\s\S]*?---\r?\n/u, '').trim()
  return {
    name,
    title: (text.match(/^#\s+(.+)$/mu)?.[1] ?? name).trim(),
    when: field('when_to_use') || field('when'),
    body,
    chars: body.length,
    /**
     * v0.32: the causal fields, read back from the SAME file. Only included when actually present, so a
     * legacy SKILL.md returns exactly the shape it always did — no invented keys, no fake defaults.
     */
    ...(field('dependencies').length === 0
      ? {}
      : { dependencies: parseEvidenceList(field('dependencies'), 'dependencies') }),
    ...(field('target_effect').length === 0 ? {} : { targetEffect: field('target_effect') }),
  }
}